import json
import os

BASE = r"C:\Users\<user>\Downloads\GTA6.Xbox.v1.0.2.1-CYBERLEEK\work\flow"

def find_in_tree(filename, needles):
    path = os.path.join(BASE, filename)
    with open(path, "r", encoding="utf-8") as f:
        data = json.load(f)
    print(f"=== {filename} (blocks={len(data.get('blocks', []))}) ===")

    def walk(obj, path_str=""):
        hits = []
        if isinstance(obj, dict):
            for k, v in obj.items():
                p = f"{path_str}.{k}"
                if isinstance(v, str) and any(n in v for n in needles):
                    hits.append((p, v))
                else:
                    hits.extend(walk(v, p))
        elif isinstance(obj, list):
            for idx, item in enumerate(obj):
                hits.extend(walk(item, f"{path_str}[{idx}]"))
        return hits

    for blk in data.get("blocks", []):
        hits = walk(blk.get("rows", []))
        if hits:
            print(f"  Block #{blk['number']} kind={blk['kind']} rows={len(blk['rows'])} hits={len(hits)}")
            for p, v in hits[:8]:
                print(f"    {p} = {v}")

if __name__ == "__main__":
    needles = [
        "d244cb70", "e48c934a", "349c946f",
        "5cb7db5c", "ab5b5242", "cc31ef42",
        "03da4607", "62131f35", "07560abe",
        "fab575e7", "bdcb784e", "55b4ae33", "8451f94f"
    ]
    find_in_tree("tree_3e2372000.json", needles)
    find_in_tree("tree_3e30b5000.json", needles)

